fn main() -> Int {
  let first_names = Vec[Str]();
  first_names.push("Alice"); first_names.push("Bob");
  let last_names = Vec[Str]();
  last_names.push("Smith"); last_names.push("Jones");

  var result = Str("");
  var i = 0;
  while i < first_names.len() && i < last_names.len() {
    if i == 0 {
      result = first_names[i] + " " + last_names[i];
    }
    i = i + 1;
  }
  return result.len();
}
